// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(amount > 0 && amount < type(uint256).max);
        address depositor = address(0xBEEF);
        vm.deal(depositor, amount);
        vm.prank(depositor);
        (bool ok,) = address(c).call{value: amount}("");
        assertTrue(ok);
        assertTrue(c.depositsCount() == 1, "depositsCount must be incremented on each deposit");
    }
}
